200       * This static method finds the offset and length of a given TLV type.
   201       *
   202       * This method can be used independent of whether the read TLV (from message) is an Extended TLV or not.
   203       *
   204       * @param[in]   aMessage    A reference to the message.
   205       * @param[in]   aType       The Type value to search for.
   206       * @param[out]  aOffset     The offset where the value starts.
   207       * @param[out]  aLength     The length of the value.
   208       *
   209       * @retval OT_ERROR_NONE       Successfully found the TLV.
   210       * @retval OT_ERROR_NOT_FOUND  Could not find the TLV with Type @p aType.
   211       *
   212       */
   213      static otError GetValueOffset(const Message &aMessage, uint8_t aType, uint16_t &aOffset, uint16_t &aLength);
   214
   215  protected:
   216      enum
   217      {
   218          kExtendedLength = 255, ///< Extended Length value
   219      };
