   221  private:
   222      /**
   223       * This private static method searches within a given message for TLV type and outputs the TLV offset, size and
   224       * whether it is an Extended TLV.
   225       *
   226       * A NULL pointer can be used for output parameters @p aOffset, @p aSize, or @p aIsExtendedTlv if the parameter
   227       * is not required.
   228       *
   229       * @param[in]   aMessage       A reference to the message to search within.
   230       * @param[in]   aType          The TLV type to search for.
   231       * @param[out]  aOffset        A pointer to a variable to output the offset to the start of the TLV.
   232       * @param[out]  aSize          A pointer to a variable to output the size (total number of bytes) of the TLV.
   233       * @param[out]  aIsExtendedTlv A pointer to a boolean variable to output whether the found TLV is extended or not.
   234       *
   235       * @retval OT_ERROR_NONE       Successfully found the TLV.
   236       * @retval OT_ERROR_NOT_FOUND  Could not find the TLV with Type @p aType.
   237       *
   238       */
   239      static otError Find(const Message &aMessage,
   240                          uint8_t        aType,
   241                          uint16_t *     aOffset,
   242                          uint16_t *     aSize,
   243                          bool *         aIsExtendedTlv);
   244
   245      uint8_t mType;
   246      uint8_t mLength;
   247  } OT_TOOL_PACKED_END;
