   250  class ExtendedTlv : public Tlv
   251  {
   252  public:
   253      /**
   254       * This method returns the Length value.
   255       *
   256       */
   257      uint16_t GetLength(void) const { return HostSwap16(mLength); }
   258
   259      /**
   260       * This method sets the Length value.
   261       *
   262       * @param[in]  aLength  The Length value.
   263       *
   264       */
   265      void SetLength(uint16_t aLength)
   266      {
   267          Tlv::SetLength(kExtendedLength);
   268          mLength = HostSwap16(aLength);
   269      }
   270
   271  private:
   272      uint16_t mLength;
   273  } OT_TOOL_PACKED_END;
