    80  otError Message::AppendOption(uint16_t aNumber, uint16_t aLength, const void *aValue)
    81  {
    82      otError  error       = OT_ERROR_NONE;
    83      uint16_t optionDelta = aNumber - GetHelpData().mOptionLast;
    84      uint16_t optionLength;
    85      uint8_t  buf[kMaxOptionHeaderSize] = {0};
    86      uint8_t *cur                       = &buf[1];
    87
    88      // Assure that no option is inserted out of order.
    89      VerifyOrExit(aNumber >= GetHelpData().mOptionLast, error = OT_ERROR_INVALID_ARGS);
    90
    91      // Calculate the total option size and check the buffers.
    92      optionLength = 1 + aLength;
    93      optionLength += optionDelta < kOption1ByteExtensionOffset ? 0 : (optionDelta < kOption2ByteExtensionOffset ? 1 : 2);
    94      optionLength += aLength < kOption1ByteExtensionOffset ? 0 : (aLength < kOption2ByteExtensionOffset ? 1 : 2);
    95      VerifyOrExit(GetLength() + optionLength < kMaxHeaderLength, error = OT_ERROR_NO_BUFS);
    96
    97      // Insert option delta.
    98      if (optionDelta < kOption1ByteExtensionOffset)
    99      {
   100          *buf = (optionDelta << kOptionDeltaOffset) & kOptionDeltaMask;
   101      }
   102      else if (optionDelta < kOption2ByteExtensionOffset)
   103      {
   104          *buf |= kOption1ByteExtension << kOptionDeltaOffset;
   105          *cur++ = (optionDelta - kOption1ByteExtensionOffset) & 0xff;
   106      }
   107      else
   108      {
   109          *buf |= kOption2ByteExtension << kOptionDeltaOffset;
   110          optionDelta -= kOption2ByteExtensionOffset;
   111          *cur++ = optionDelta >> 8;
   112          *cur++ = optionDelta & 0xff;
   113      }
   114
   115      // Insert option length.
   116      if (aLength < kOption1ByteExtensionOffset)
   117      {
   118          *buf |= aLength;
   119      }
   120      else if (aLength < kOption2ByteExtensionOffset)
   121      {
   122          *buf |= kOption1ByteExtension;
   123          *cur++ = (aLength - kOption1ByteExtensionOffset) & 0xff;
   124      }
   125      else
   126      {
   127          *buf |= kOption2ByteExtension;
   128          optionLength = aLength - kOption2ByteExtensionOffset;
   129          *cur++       = optionLength >> 8;
   130          *cur++       = optionLength & 0xff;
   131      }
   132
   133      SuccessOrExit(error = Append(buf, static_cast<uint16_t>(cur - buf)));
   134      SuccessOrExit(error = Append(aValue, aLength));
   135
   136      GetHelpData().mOptionLast = aNumber;
   137
   138      GetHelpData().mHeaderLength = GetLength();
   139
   140  exit:
   141      return error;
   142  }
